function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xd8e4ff;
    ambient.brightness = 380;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.35) });
    world.add(sun, DirectionalLight, { color: 0xfff4e6, illuminance: 6000 });
    world.storage(DirectionalLight).shadowMapsEnabled.set(sun, 1);

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x191816 });
    world.add(camera, StandardRenderer);
    world.add(camera, Orbit, { distance: 12, yaw: 0.7, pitch: 0.3, target: [0, 2, 0] });
    world.add(camera, Transform);

    const materials = world.resource(Materials);

    // Static floor: unit cube mesh and collision hull, scaled into a slab whose top is y = 0.
    const floor = world.create();
    world.add(floor, Transform, {
        translation: [0, -FLOOR_THICKNESS / 2, 0],
        scale: [10, FLOOR_THICKNESS, 10],
    });
    world.add(floor, Body, { type: BodyType.Static });
    world.add(floor, Shape);
    world.add(floor, MeshInstance);
    world.add(
        floor,
        MeshMaterial,
        materials.add(StandardMaterial({ baseColor: [0.5, 0.5, 0.5, 1], perceptualRoughness: 0.9 })),
    );
    world.add(floor, Floor);

    // Dynamic 1 m box, starting up in the air.
    const box = world.create();
    world.add(box, Transform, { translation: [0, START_HEIGHT, 0] });
    world.add(box, Body, { type: BodyType.Dynamic });
    world.add(box, Shape);
    world.add(box, MeshInstance);
    world.add(
