        MeshMaterial,
        materials.add(StandardMaterial({ baseColor: [0.05, 0.25, 0.95, 1], perceptualRoughness: 0.5 })),
    );
    world.add(box, DropBox);
}

export const Drop: Plugin = {
    name: "Drop",
    components: [DropBox, Floor],
    dependencies: [StandardPhysicsPlugin, OrbitPlugin],
    initialize: makeScene,
};
